INSERT INTO "RecordDefinition" ("recordKey","engine","mount","pageFile","docCode","title","docRevisionStart","jobInfoGroup","clientHook","primaryBatchField","extraBatchFields","extraJson","version","updatedAt") VALUES ('closed-box-inspection','form-record','#frRoot','REC-7.4.5-closed-box-inspection.html','REC 7.4.5','Closed Box Inspection',1,NULL,NULL,NULL,ARRAY[]::text[],'{"stage":"closed-box-inspection","boxInspection":true,"listColumns":["outstandingNote"],"instructions":[{"label":"How this works","text":"Every box closed with + Full box in REC 7.4.3.1 / 7.4.3.2 appears here until its inspection is submitted. Weigh the tare, type the nett weight (it must equal the weight set in 7.4.3), then tick every check that is satisfactory. A box you do not touch is not recorded and stays on the list. The packing date is stamped automatically when you submit."}]}'::jsonb,1,now());
